function showLineage(nodeName,id){const n=state.data.nodes.find(n=>n.node===nodeName),r=n?.template_rows.find(r=>r.id===id);if(!r)return;const d=r.actual_decision,b=n.pipeline.batches.find(b=>b.key===d?.batch_key),call=b?.attempts[b.accepted_attempt??b.attempts.length-1],series=state.data.pipeline.metric_sources[r.metric_source_key];const appearances=r.appearances||[],cites=r.citations||[];const rowstates=state.data.story.rounds.map(round=>{const archived=round.archive.facts.find(f=>f.source_id===r.source_id),visible=round.snapshot?.evidence.find(e=>e.source_id===r.source_id),used=cites.filter(c=>c.round===round.index);return{round:round.index,archived,visible,used};});openInspector("一项观测的完整来路与去向",`${n.node} · ${r.subject}`,`<div class="mini-chip-row">${tag(r.id,"blue")}${tag(r.central_id||"没有初始中央编号")}${tag(...choice(r))}</div><ol class="path-list panel-section"><li><strong>${role("program")} 保存原始记录</strong><p>${series?`该节点该指标保留 ${fmt(series.total)} 条原始记录，本页载入 ${fmt(series.shown)} 条。`:"这项来自本地工具记录；可以根据程序事实和来源路径核对。"}</p><p class="mono">frames/inbox.sqlite</p>${series?.samples?.[0]?.source_file?`<p class="small-text">原始文件样本：${esc(series.samples[0].source_file)} · 行 ${esc(series.samples[0].source_row)}</p>`:""}</li><li><strong>${role("program")} 整理为本地观测 <code>${esc(r.id)}</code></strong><p>程序计算统计、规则、时间及来源字段；这些数值不由4B计算。</p>${docButton({raw_fact:r.raw_fact,fields:r.fields,source_record_ids:r.source_record_ids},"程序事实与来源","查看完整程序事实 ↗")}</li><li><strong>${role("4b")} 在目录第 ${esc(d?.page??"未知")} 页作出选择</strong><p>模型本页编号 <code>${esc(d?.input_id||"未匹配")}</code> → ${esc(choice(r)[0])}。${esc(choiceSource(d))}</p>${call?docButton({messages:call.messages,raw_reply:call.raw_reply,validation:call.validation},"对应的4B实际输入与回复","核对原始调用 ↗"):""}</li><li><strong>${role("program")} 装配节点报告与中央编号</strong><p><code>${esc(d?.input_id||"fID未知")}</code> → <code>${esc(r.id)}</code> → <code>${esc(r.central_id||"未进入初始中央候选")}</code></p>${r.selection_source==="program_generated"?`<p>${tag("此解释为程序自动补写","amber")} ${esc(r.reading_options?.[r.selection?.reading]||readings[r.selection?.reading]||r.selection?.reading)}。4B没有在本次回复中填写这个reading。</p>`:r.selection_source==="model"?`<p>这一项有4B实际逐项填写记录，可展开核对。</p>`:`<p>没有保存逐项模型解释。</p>`}</li><li><strong>${role("program")} 按每轮预算装入9B输入</strong><p>在 ${appearances.length} 轮决策证据列表中出现。是否进入候选库、是否实际载入、是否被引用，见下面逐轮对照。</p></li><li><strong>${role("9b")} 形成判断与最终引用</strong><p>${cites.length?`保存记录中有 ${cites.length} 处支持、反证或最终答案引用。引用只是模型行为，并不证明根因正确。`:"保存的假设和最终答案没有引用这项观测。"}</p></li></ol>`+section("这项观测在每轮发生了什么",table("lineage-rounds",["轮次","中央候选库","实际输入","假设中的引用"],rowstates,x=>`<tr><td>第 ${x.round+1} 轮</td><td>${x.archived?`<code>${esc(x.archived.id)}</code>`:"未收录"}</td><td>${x.visible?idButton(x.visible.id,state.data.story.rounds.find(r=>r.index===x.round).snapshot.key):tag(x.archived?.index_mentioned?"仅索引提到":"未载入",x.archived?.index_mentioned?"amber":"")}</td><td>${x.used.length?x.used.map(c=>`<p>${esc(c.role==="support"?"支持":"反证")}：${esc(c.component||"未知组件")} · ${esc(reasons[c.reason]||c.reason||"原因未知")}</p>`).join(""):"无引用"}</td></tr>`,{search:false,pageSize:10}))+section("保存的报告选择字段",codeBlock(r.selection||{},"报告中的选择字段")+`<p class="small-text inline-spacer">字段来源：${r.selection_source==="program_generated"?"目录上报后由程序合成详细选择字段":"模型选择或无选择，详见原始调用"}。</p>`)+`<button class="button primary inline-spacer" data-action="jump-fact" data-node="${esc(n.node)}" data-id="${esc(r.id)}" data-kind="facts">以这一项继续逐步跟踪 →</button>`);}
function showGlobal(id){const g=state.data.pipeline.global,item=g.items.find(i=>i.id===id||i.source_fact_id===id);if(!item)return;openInspector("独立全局信息的完整交接",`${item.id||item.source_fact_id} · ${String(item.fact||"").split("；")[0]}`,`<div class="mini-chip-row">${role("program")}${tag(item.kind==="business"?"业务表统计":"实际调用连接")}${tag(item.kept?(g.result.fallback?"回退后保留":"过滤后保留"):"过滤后移出",item.kept?"green":"amber")}</div>`+section("1. 程序实际保存的内容",`<div class="raw-text">${esc(item.fact)}</div><p class="small-text inline-spacer">时间标记：${esc(item.time_marks.join("、")||"无")}</p>`)+section("2. 过滤9B实际收到的内容",item.filter_views.length?item.filter_views.map(v=>`<p class="small-text">调用：<code>${esc(v.phase)}</code></p>${literalDetails(v.fact)}`).join(""):empty("实际过滤输入中没有匹配到此编号。"))+section("3. 程序采纳后的去向",notice(item.kept?`本项被保留在中央候选库。${g.result.fallback?"原因是过滤失败后程序回退保留，而非模型有效选择。":"这是程序接受的9B筛选结果。"}`:"本项没有保留在这版中央视图中。原始记录还在frames，但后续本轮中央页索引无法再按这个编号读取它。",item.kept?"":"warning")+`<p class="small-text inline-spacer">决策证据列表出现于：${item.appearances.length?item.appearances.map(a=>`第 ${a.round+1} 轮 ${idButton(a.id,a.snapshot)}`).join("、"):"没有匹配到"}</p>`)+section("4. 被哪些判断引用",item.citations.length?item.citations.map(c=>`<div class="quote">${c.round==="final"?"最终答案":`第 ${c.round+1} 轮`} · ${esc(c.role)} · ${esc(c.component||"未知")} · ${esc(c.reason||"未知")}</div>`).join(""):empty("假设或最终答案没有引用这项全局观测。"))+sourceNote(g.source_file));}
function showProvenance(){const d=state.data;openInspector("案例来源与统计口径",`Bank · row ${d.case.row}`,`<dl class="key-values"><dt>案例目录</dt><dd><code>${esc(d.case.path)}</code></dd><dt>冻结源码</dt><dd><code>${esc(d.case.source_sha256)}</code></dd><dt>公开时间窗</dt><dd>${esc(clock(d.case.window_start_ms,true))} — ${esc(clock(d.case.cutoff_ms,true))}</dd><dt>原始记录</dt><dd>${fmt(d.raw.total)} 条</dd><dt>程序节点观测</dt><dd>${fmt(d.flow.facts)} 项</dd><dt>4B实际目录展示</dt><dd>${fmt(d.flow.catalogue_seen)} 项</dd><dt>中央初始候选</dt><dd>${fmt(d.pipeline.initial_archive.count)} 项</dd><dt>首轮实际证据</dt><dd>${fmt(d.story.rounds[0]?.snapshot?.evidence.length)} 项</dd></dl>${notice("原始记录、程序观测、模型输入和假设是不同单位，不能相除当作转化率。页面完整列出各类清单，原始数据只嵌入可追溯样本和选定指标的采样；未嵌入部分会明确标出。")}${reveal("程序、4B和9B各做了什么",codeBlock({program:["路由保存","统计与规则计算","分批和校验","装配节点报告与中央索引","压缩并装入上下文","执行固定工具","冻结后评分"],model_4b:["首轮目录筛选","定向补查中的有限解释"],model_9b:["全局相关性筛选","比较假设与证据","提出补查","最终裁决"]},"职责对照"))}`);}
function showDoc(index){const obj=state.docs[index];if(obj)openInspector("保存的完整记录",obj.title,codeBlock(obj.value,obj.title));}
function toast(text){$("toast").textContent=text;$("toast").hidden=false;setTimeout(()=>$("toast").hidden=true,2300);}
async function copyDoc(index){const value=state.docs[index]?.value,text=typeof value==="string"?value:json(value);try{await navigator.clipboard.writeText(text);toast("已复制完整记录");}catch{const area=document.createElement("textarea");area.value=text;area.style.position="fixed";area.style.left="-10000px";document.body.append(area);area.select();const ok=document.execCommand("copy");area.remove();toast(ok?"已复制完整记录":"浏览器禁止复制，可使用下载记录");}}
function downloadDoc(index){const doc=state.docs[index];if(!doc)return;const text=typeof doc.value==="string"?doc.value:json(doc.value);const url=URL.createObjectURL(new Blob([text],{type:"application/json;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download=`EdgeRCA_row${state.data.case.row}_${doc.title.replace(/[\\/:*?"<>|]/g,"_")}.${typeof doc.value==="string"?"txt":"json"}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function selectFact(node,id){stopPlay();state.node=node||state.node;state.fact=id;state.tableViews={};state.batches={};render();}
function handleAction(event){const el=event.target.closest("[data-action]");if(!el||!state.data)return;stopPlay();const a=el.dataset.action;
 if(a==="step")go(Number(el.dataset.index),true);
 else if(a==="stage"){const i=state.data.pipeline.steps.findIndex(s=>s.stage===Number(el.dataset.stage));if(i>=0)go(i,true);}
 else if(a==="table-page"){state.tableViews[el.dataset.table].page=Number(el.dataset.page);updateTable(el.dataset.table);}
 else if(a==="attempt"){state.attempts[el.dataset.key]=Number(el.dataset.attempt);render();}
 else if(a==="doc")showDoc(Number(el.dataset.doc));
 else if(a==="copy-doc")copyDoc(Number(el.dataset.doc));
 else if(a==="download-doc")downloadDoc(Number(el.dataset.doc));
 else if(a==="evidence")showEvidence(el.dataset.id,el.dataset.snapshot);
 else if(a==="lineage")showLineage(el.dataset.node,el.dataset.id);
 else if(a==="global-detail")showGlobal(el.dataset.id);
 else if(a==="select-fact")selectFact(state.node,el.dataset.id);
 else if(a==="select-node"){const n=state.data.nodes.find(n=>n.node===el.dataset.node);selectFact(n.node,n.template_rows.find(r=>r.actual_decision?.action==="report")?.id||n.template_rows[0]?.id);}
 else if(a==="jump"){if($("inspector").open)$("inspector").close();jumpKind(el.dataset.kind,el.dataset.round===undefined?undefined:Number(el.dataset.round));}
 else if(a==="jump-fact"){if($("inspector").open)$("inspector").close();state.node=el.dataset.node;state.fact=el.dataset.id;state.batches={};jumpKind(el.dataset.kind);}
 else if(a==="raw-point"){const point=metricSource()?.samples[Number(el.dataset.index)];if(point)openInspector("原始采样与来源",`${state.node} · ${clock(point.observed_ms)}`,codeBlock(point,"原始采样记录"));}
}
async function init(){if(location.protocol==="file:"&&!window.__TRACE_DATA__){location.replace(new URL("EdgeRCA_trace.html",location.href));return;}document.addEventListener("click",handleAction);document.addEventListener("input",e=>{if(e.target.matches("[data-table-search]")){stopPlay();const name=e.target.dataset.tableSearch;state.tableViews[name].query=e.target.value;state.tableViews[name].page=0;updateTable(name);}});document.addEventListener("change",e=>{if(e.target.matches("[data-table-filter]")){const name=e.target.dataset.tableFilter;state.tableViews[name].filter=e.target.value;state.tableViews[name].page=0;updateTable(name);}else if(e.target.id==="batch-select"){state.batches[state.node]=e.target.value;render();}});
 $("case-select").addEventListener("change",e=>loadCase(e.target.value));$("node-select").addEventListener("change",e=>{stopPlay();const n=state.data.nodes.find(n=>n.node===e.target.value);state.node=n.node;state.fact=n.template_rows.find(r=>r.actual_decision?.action==="report")?.id||n.template_rows[0]?.id;state.tableViews={};render();});$("fact-select").addEventListener("change",e=>selectFact(state.node,e.target.value));
 $("trace-selected").addEventListener("click",()=>showLineage(state.node,state.fact));$("close-inspector").addEventListener("click",()=>$("inspector").close());$("provenance").addEventListener("click",()=>state.data&&showProvenance());$("previous").addEventListener("click",()=>go(state.step-1));$("next").addEventListener("click",()=>go(state.step+1));$("bottom-next").addEventListener("click",()=>go(state.step+1,true));$("play").addEventListener("click",()=>{if(state.timer){stopPlay();return;}if(state.step===state.data.pipeline.steps.length-1)go(0);$("play").textContent="Ⅱ 暂停播放";state.timer=setInterval(()=>{if(state.step>=state.data.pipeline.steps.length-1){stopPlay();return;}go(state.step+1,false,false);},7000);});
 document.addEventListener("keydown",e=>{if((e.key==="Enter"||e.key===" ")&&e.target.matches(".chart-point")){e.preventDefault();e.target.dispatchEvent(new MouseEvent("click",{bubbles:true}));return;}if($("inspector").open||/INPUT|SELECT|TEXTAREA|SUMMARY/.test(document.activeElement?.tagName||""))return;if(e.key==="ArrowRight"&&state.data){e.preventDefault();go(state.step+1);}if(e.key==="ArrowLeft"&&state.data){e.preventDefault();go(state.step-1);}});
 try{state.index=await readData("data/index.json");$("case-select").innerHTML=state.index.cases.map((c,i)=>`<option value="${esc(c.name)}">案例 ${i+1} · row ${c.row} · ${esc(c.label?.split(" · ").slice(1).join(" · ")||"Bank")}</option>`).join("");$("case-select").value=state.index.default;await loadCase(state.index.default);}catch(err){$("load-error").textContent=err.message;$("load-error").hidden=false;}
}
init();
function renderAvailability(r,n){const rows=n.template_rows.filter(x=>materialCategory(x)==="availability"),raw=n.pipeline.coverage?.raw_by_modality||{};return programCoverage()+factHeading()+notice("这里记录的是本组件有哪些材料可用。Redis02 之类的节点没有日志或调用记录时，程序也会生成范围说明，提醒4B不能把“没记录”理解成“没故障”。这类说明不属于任何 kpi_name。")+section(`${n.node} 的材料可用性（合并展示）`,table("availability",["材料类别","本范围原始条数","实际说明 / 原编号","当时4B的处理"],rows,x=>{const f=x.raw_fact||{},modality=f.modality||(f.kind==="log"?"log":"metric"),c=choice(x);return `<tr><td><strong>${esc(modalityNames[modality]||modality)}</strong></td><td class="numeric">${fmt(raw[modality]||0)}</td><td>${esc(factTitle(x))}<br>${localButton(x.id)}</td><td>${tag(c[0],c[1])}<p class="small-text">${esc(choiceSource(x.actual_decision))}</p></td></tr>`;},{search:false,pageSize:8}))+notice("页面把这些状态合在组件下展示；当时实验实际发送的两条材料、原编号和模型回复均可单独追溯。没有把它们改挂到某个指标，也没有补造原始证据。")+reveal("查看当前说明的原始字段",codeBlock(r.raw_fact,"程序生成的材料可用性说明")+sourceNote(r.source_files.packet));}
function renderOtherFacts(r,n){if(materialCategory(r)==="availability")return renderAvailability(r,n);const raw=r.raw_fact||{},f={...raw,...(r.fields||{})};let title="程序整理的记录",items=[];
 if(r.template==="connection"){title="实际调用连接";items=[["源组件",f.from],["目标组件",f.to],["子调用统计",json(f.child_latency_ms||{})],["区间不满足包含关系的数量",f.interval_mismatch_count],["解释边界","匹配到了连接，不等于已证明传播方向、网络RTT或因果"]];}
 else if(materialCategory(r)==="call_alarm"){title="从调用记录计算的告警规则";items=[["规则含义",factTitle(r)],["规则状态",f.state],["第一次触发的观测",json(f.first_trigger_values||{})],["状态变化时间线",json(f.timeline||[])],["与KPI的区别","这是程序根据调用耗时触发的规则，不是原始 metric 数据中的 kpi_name；与本组件调用统计归在一组"]];}
 else if(r.template==="call_latency"){const c=f.current||f;title="调用耗时统计";items=[["调用数量",c.count],["P50 / P95 / 最大值",`${c.p50??"—"} / ${c.p95??"—"} / ${c.max??"—"} ms`],["已有参考段",json(f.reference||{})],["长调用样本",json(f.slow_calls||[])],["解释边界","P95与最大值不同；总调用数不是慢调用数，也没有调用失败率字段"]];}
 else if(r.template==="log_event"){title="日志聚合与事件类型";items=[["日志类别",factTitle(r)],["HTTP状态码",f.status||"本日志类型不适用"],["记录数量",f.count],["归并的日志模板数",f.template_count??"未按状态码归并"],["首次 / 最后观测",`${f.first||"—"} / ${f.last||"—"}`],["程序识别的错误标记",String(f.explicit_error??"未设置")],["解析内容",json(f.details||{})],["解释边界","普通访问日志按状态码归并；GC按事件类型整理。它们属于日志，不是指标采样，不能任意归到同组件某个KPI下"]];}
 else if(r.template==="unavailable"){title="材料和工具可见范围";items=[["工具材料类别",f.modality||raw.modality||raw.kind],["缺失的指定名称",json(f.missing_requested_names||[])],["已给出的名称或状态",json(f.names||f.status||f.note||{})],["解释边界","缺少某个名称或某种材料，不等于设备正常或所有数据缺失"]];}
 else{title="规则或其他程序观测";items=Object.entries(f).map(([k,v])=>[k,typeof v==="object"?json(v):v]);}
 const linked=(r.sample_record_ids||[]).map(id=>state.data.pipeline.source_records?.[id]).filter(Boolean);
 return programCoverage()+factHeading()+`<div class="split"><div class="subpanel"><div class="comparison-label">${role("program")} ${esc(title)}</div>${table("other-fields",["程序字段","保存的值"],items,([k,v])=>`<tr><td>${esc(k)}</td><td class="subject-cell mono">${esc(v??"未保存")}</td></tr>`,{search:false,pageSize:20})}</div><div class="subpanel tint"><h3>这项如何形成</h3><p>程序读取本地记录，按固定工具计算或聚合，再将这些字段交给节点。原始事实与模型选择分别保存。</p><div class="inline-spacer">${docButton(raw,"完整程序事实")}</div><div class="inline-spacer">${docButton(f,"提供给节点表单的完整字段")}</div><p class="small-text inline-spacer">本地编号：<code>${esc(r.id)}</code>。选中的表单类型：<code>${esc(r.template)}</code>。</p></div></div>`+
 section("可追溯到的原始记录样本",linked.length?table("source-samples",["观测时间","原始内容","来源","查看"],linked,p=>`<tr><td class="numeric">${esc(clock(p.observed_ms))}</td><td class="subject-cell">${esc(short(p.raw,200))}</td><td class="mono">${esc(p.source_file)}<br>行 ${esc(p.source_row)}</td><td>${docButton(p,"来源原始记录","完整原文 ↗")}</td></tr>`,{search:false,pageSize:5}):notice("此观测未解析到可嵌入的来源样本。完整事实与来源编号仍可展开核对，不能把本节点其他样本冒充本项原文。"),`仅嵌入本项明确来源编号中的前3条；保留的来源编号共有 ${r.source_record_ids?.length||0} 个。`)+reveal("查看全部保存的来源编号",codeBlock(r.source_record_ids||[],"来源记录编号")+sourceNote(r.source_files.packet));}
function readableStats(s){if(!s||!Object.keys(s).length)return "未提供";return `${s.count??"样本数未知"} 个采样；中位数 ${s.median??"未知"}${s.min!==undefined?`；范围 ${s.min}～${s.max}`:""}`;}
function readableExtremes(values){if(!Array.isArray(values)||!values.length)return "未提供极值观测";return values.map(e=>Array.isArray(e)?`${e[0]??"时间未知"} → ${e[1]??"数值未知"}`:`${e.time??(e.time_ms?clock(e.time_ms):"时间未知")} → ${e.value??"数值未知"}`).join("；");}
function readableObservation(value){if(value===null||value===undefined)return "没有保存统计概要";if(typeof value!=="object")return String(value);const n=value["n,min,max,median"];if(Array.isArray(n)){const early=value["early,late_median"],unit=value.unit;return `${n[0]??"—"} 个采样；范围 ${n[1]??"—"}～${n[2]??"—"}；中位数 ${n[3]??"—"}；单位 ${unit==="source_unit_unverified"?"尚未核实":unit??"未知"}${early?`；前/后段中位数 ${early[0]??"—"} → ${early[1]??"—"}`:""}${Array.isArray(value.extremes)&&value.extremes.length?`；极值 ${readableExtremes(value.extremes)}`:""}`;}if(value.from&&value.to)return `${value.from} → ${value.to}；子调用 ${value.child_latency_ms?.calls??"—"} 次，P95 ${value.child_latency_ms?.p95??"—"} ms，最大 ${value.child_latency_ms?.max??"—"} ms；区间不满足包含关系 ${value.interval_mismatch_count??"—"} 对`;const c=value.current||value;if(c.p95!==undefined)return `${c.count??"—"} 次调用；P50 ${c.p50??"—"} ms；P95 ${c.p95??"—"} ms；最大 ${c.max??"—"} ms${value.reference?`；参考段P95 ${value.reference.p95??"未知"} ms`:""}`;if(value.category)return `类别 ${value.category}；${value.count??"—"} 条；首次 ${value.first??"—"}，最后 ${value.last??"—"}；明确错误标记 ${value.explicit_error??"未设置"}`;const labels={unit:"单位",metric_unit:"单位",extremes:"极值观测",reference:"已有对照",early:"早段",late:"后段",state:"规则状态",count:"数量",signal:"信号",first_trigger_values:"首次触发观测",timeline:"规则记录",names:"指标名称",modality:"材料类别",missing_requested_names:"未找到的指定名称"};return Object.entries(value).map(([k,v])=>`${labels[k]||k}：${typeof v==="object"?JSON.stringify(v):v}`).join("；");}
function renderNodeGrid(){const a=state.data.pipeline.initial_archive;return `<div class="node-grid">${state.data.nodes.map(n=>{const own=a.facts.filter(f=>f.node_id===`device:${n.node}`);return `<button class="node-tile ${n.node===state.node?"active":""}" data-action="select-node" data-node="${esc(n.node)}"><strong>${esc(n.node)}</strong><span>本地 ${n.facts} 项 · 上报 ${n.pipeline.counts.report||0}</span><span>中央收录 ${own.length} · 首轮载入 ${own.filter(f=>f.loaded).length}</span></button>`;}).join("")}</div><div class="quote">设备节点的4B筛选结果 → 程序装配与编号绑定 → 中央9B的输入、假设和定向补查</div>`;}
function nodeSummaryTable(metadata,archive){const rows=metadata.node_summaries||[];const interpretations=metadata.node_interpretations_unverified||[];let generated=0;for(const item of interpretations){const source=archive.binding[item.basis_id]?.source_id;if(!source)continue;const r=state.data.nodes.flatMap(n=>n.template_rows).find(r=>r.source_id===source);if(r?.selection_source==="program_generated")generated++;}return (generated?notice(`这轮共有 ${interpretations.length} 条“节点解释”字段，其中 ${generated} 条能追溯到首轮<strong>程序自动补写</strong>，不能当作4B逐项解释。`,"warning"):"")+notice("原始节点概览中的‘其余/未载入’包含未进入中央候选库的本地材料；它不是候选库未装入证据列表的数量。这里原样保留概览计数，具体交接见‘交给中央’步骤。")+table(`node-summaries-${currentStep().round}`,["节点","概览声明的材料 / 本轮载入 / 其余（含未上报）","本轮提供的概览文字"],rows,r=>`<tr><td><strong>${esc(r.node_id?.split(":").at(-1))}</strong></td><td class="numeric">${fmt(r.available_fact_count)} / ${fmt(r.loaded_fact_count)} / ${fmt(r.unloaded_fact_count)}</td><td class="subject-cell">${esc(r.text_unverified||"这一项只保留计数，未提供概览文字")}</td></tr>`,{pageSize:9,placeholder:"搜索节点或概览中的内容…"});}
function programCoverage(){
 const n=selectedNode(),p=n.pipeline,c=p.coverage||{},names=c.metric_names||[],parts=Object.entries(c.raw_by_modality||n.raw_by_modality||{}).filter(([,v])=>v),categories=c.categories||{},unlisted=c.unlisted_metric_names??p.scope?.cpu_only_metric_count;
 const rawEquation=parts.map(([k,v])=>`${fmt(v)} 条${k==="metric"?"指标采样":k==="trace"?"调用记录":modalityNames[k]||k}`).join(" ＋ ");
 const materialEquation=Object.entries(categories).filter(([,v])=>v).map(([k,v])=>`${v} 条${materialNames[k]||k}`).join(" ＋ ");
 const reasonNames={alarm_history:"曾触发指标规则，保留规则历史与统计",alert:"触发规则",control:"固定对照指标",window_change:"满足参考段/当前段变化阈值",quality:"存在数据质量标记"};
 const selectedDetails=names.filter(x=>x.included).flatMap(x=>x.materials||[]),references=selectedDetails.map(m=>m.reference_count),noReferences=references.length&&references.every(v=>v===0);
 const metricRows=names.map(x=>({...x,_status:x.included?"included":"unlisted",_search:x.name+" "+(x.materials||[]).flatMap(m=>m.reasons||[]).join(" ")}));
 const selectionPolicy=c.policy_verified_from_frozen_source?`<ol class="change-list"><li>保留曾触发告警的指标，将规则历史和该指标的采样统计合为一条材料。</li><li>再补充固定对照指标，例如整机 CPU、内存和配置中指定的 JVM 指标。</li><li>补充满足变化条件的指标：参考段与当前段采样充足，且两段中位数之比 ≥ 1.5，或在 0～0.5 之间。</li><li>补充有无效值、同一时刻数值冲突或累计计数重置标记的指标。</li><li>其余指标的统计留在本地，未进入首轮 4B 目录。这个筛选由程序完成。</li></ol>`:notice("此案例缺少可核对的固定筛选源码，下面仅展示保存下来的入选结果，不推断排除原因。","warning");
 return stats([[n.raw,"原始记录：按条计数"],[c.metric_name_count,"不同 kpi_name：去重计数"],[c.represented_metric_names,"进入首轮材料的 KPI 种类"],[c.card_count??n.facts,"首轮材料：包含指标、日志、调用等"]])+
 section("这些数字怎样对应？",`<div class="count-story"><div class="count-stage"><span class="eyebrow">① 原始记录</span><strong>${fmt(n.raw)} 条 ＝ ${esc(rawEquation)}</strong><p>同一 KPI 在不同时间采样，会产生多条记录；调用与日志是另外的数据类型。</p></div><div class="count-stage"><span class="eyebrow">② 仅看指标</span><strong>${fmt(c.metric_name_count)} 种 kpi_name ＝ ${fmt(c.represented_metric_names)} 种进入首轮 ＋ <span class="omitted-count">${fmt(unlisted)} 种未进入首轮</span></strong><p>${fmt(c.raw_by_modality?.metric)} 条指标采样按完整 kpi_name 分组，得到 ${fmt(c.metric_name_count)} 条时间序列。未进入的 ${fmt(unlisted)} 种没有交给首轮 4B 筛选。</p></div><div class="count-stage"><span class="eyebrow">③ 送入 4B 的材料</span><strong>${fmt(c.card_count??n.facts)} 条 ＝ ${esc(materialEquation)}</strong><p>这一步包括采样聚合、程序筛选，以及生成调用关系和缺失说明。材料条数不等于 KPI 种类数，也不等于原始记录数。</p></div></div>`)+
 notice(`<strong>“未进入首轮”是程序筛选的结果。</strong>它与4B读过后选择“暂留本地”是两个阶段。原始记录仍在；这些指标仍可能被定向补查，但不能算成模型已经检查，也不能算正常。`,"warning")+
 (c.omission_count_matches===false?notice(`名称差集有 ${fmt(unlisted)} 种，保存的未入表统计为 ${fmt(c.saved_unlisted_metric_observations)} 项，计数未完全对应，需要分别核对。`,"error"):"")+
 reveal(`为什么 ${fmt(unlisted)} 种指标未进入首轮？查看程序的筛选条件`,selectionPolicy+(noReferences?notice(`已入表的 ${fmt(references.length)} 条指标材料，其保存的参考段采样数均为 0。“参考段/当前段变化”条件要求足够参考采样；本例不能靠这项条件覆盖全部指标。告警历史来自另一套规则。`,"warning"):"")+`<p class="small-text">“程序统计”过去在页面中写成“CPU观测”，它指在 CPU 上计算的本地统计，不是专指 CPU 使用率。逐指标的入选原因保留在下面的列表中。</p>`)+
 reveal(`查看全部 ${fmt(c.metric_name_count)} 种 KPI，或只看未进入的 ${fmt(unlisted)} 种`,table("local-metric-catalogue",["原始 kpi_name","原始采样条数","首轮状态 / 对应材料","程序选入依据"],metricRows,x=>`<tr><td class="mono subject-cell">${esc(x.name)}</td><td class="numeric">${fmt(x.raw_samples)}</td><td>${tag(x.included?"已形成首轮材料":"未进入首轮 4B",x.included?"green":"amber")}<br>${(x.materials||[]).map(m=>localButton(m.id)).join(" ")}</td><td class="subject-cell">${x.included?esc([...new Set(x.materials.flatMap(m=>(m.reasons||[]).map(r=>reasonNames[r]||r)))].join("；")):"未被告警历史或上述固定筛选条件选入；这是程序排除，并非4B判断"}</td></tr>`,{pageSize:10,placeholder:"搜索完整 KPI 名称…",filters:[["all","全部 KPI"],["unlisted","只看未进入首轮"],["included","只看已进入首轮"]]}))+
 reveal(`这 ${fmt(c.card_count??n.facts)} 条材料分别是什么？按类型查看`,notice("同一组件的日志和调用已按类型归组。它们有自己的来源，不能仅因组件相同就挂到某个 KPI 下。材料缺失统一放在组件的“材料可用性”组中；保留原编号，以便核对当时4B收到的内容。")+table("material-types",["材料编号","类型","具体含义"],n.template_rows,r=>`<tr><td>${localButton(r.id)}</td><td>${esc(materialNames[materialCategory(r)])}</td><td class="subject-cell">${esc(factTitle(r))}</td></tr>`,{pageSize:10,placeholder:"搜索类型、编号或内容…"}))+
 reveal("核对原始范围、程序源码与限制",(p.limitations||[]).map(x=>`<p class="small-text inline-spacer">${esc(x)}</p>`).join("")+docButton({scope:p.scope,coverage:c,unrepresented_metric_observation_ids:p.cpu_only_metric_ids},"程序范围与未入表的指标观测ID")+(c.source_files||[]).map(sourceNote).join(""))+`<div class="section-divider"></div>`;
}
function packingExplanation(snap){const p=state.data.pipeline.packing_policy||{},om=snap.omissions||{},duplicates=Object.keys(om.duplicates||{}).length;const limit=p.context_limit;const bar=limit?`<div class="token-bar"><i style="width:${Math.min(100,(snap.input_tokens||0)/limit*100)}%"></i></div><div class="token-legend"><span>实际输入 ${fmt(snap.input_tokens)} tokens</span><span>总上下文上限 ${fmt(limit)}；同时需为输出${p.repair_reserve?`及 ${p.repair_reserve} tokens 修正预算`:""}留空间</span></div>`:"";return `${bar}<ol class="change-list"><li>将工具事实转换为概要。长文本、长列表可能只留下长度或首尾提示，完整内容需要读详情页。</li>${p.deduplicates?`<li>合并完全相同的当前展示；本轮记录了 ${duplicates} 个重复别名，不合并不同数值或不同范围。</li>`:""}<li>装入已经要求读取的详情页，并用实际分词器计算输入长度。</li>${p.cross_node_priority?`<li>超出预算时，优先保留显式请求页，尽量保留不同节点的覆盖，再考虑旧引用、补查与保护项；仍装不下时继续缩减。</li>`:`<li>超出预算时缩减当前展示范围，完整未载入条目仍按目录状态记录。</li>`}<li>把最终证据列表、节点概览和候选索引交给9B。索引中提到编号，不等于明细已经载入。</li></ol><p class="small-text inline-spacer">来源：<code>${esc(p.source_file||"本题上下文省略记录")}</code></p>`;}
